+          key: { type: 'string', minLength: 1 },
+          value: { type: 'string' }
+        },
+        required: ['session_id', 'key', 'value'],
+        additionalProperties: false
+      }
+    },
+    {
+      name: 'get_value',
+      description: 'Retrieve the value for a key within a session.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          session_id: { type: 'string', minLength: 1 },
+          key: { type: 'string', minLength: 1 }
