+}
+
+export async function callTool(name, args = {}) {
+  switch (name) {
+    case 'begin_session': {
+      validateArgs(args, ['session_id']);
+      requireNonEmptyString(args.session_id, 'session_id');
+      sessions.set(args.session_id, new Map());
+      return { session_id: args.session_id };
+    }
+    case 'put_value': {
+      validateArgs(args, ['session_id', 'key', 'value']);
+      requireNonEmptyString(args.session_id, 'session_id');
+      requireNonEmptyString(args.key, 'key');
+      requireString(args.value, 'value');
+      const store = requireSession(args.session_id);
+      store.set(args.key, args.value);
+      return { ok: true, session_id: args.session_id, key: args.key };
+    }
+    case 'get_value': {
+      validateArgs(args, ['session_id', 'key']);
+      requireNonEmptyString(args.session_id, 'session_id');
+      requireNonEmptyString(args.key, 'key');
+      const store = requireSession(args.session_id);
+      if (!store.has(args.key)) {
+        throw new Error(`key not found in session: ${args.key}`);
+      }
+      return { value: store.get(args.key) };
+    }
+    default:
+      throw new Error(`unknown tool: ${name}`);
+  }
